check-if-every-row-and-column-contains-a:
class Solution:
    def checkValid(self, matrix: List[List[int]]) -> bool:
        n = len(matrix)
        for row in matrix:
            if sorted(row) != list(range(1, n + 1)):
                return False
        for col in zip(*matrix):
            if sorted(col) != list(range(1, n + 1)):
                return False
        return True

check-if-grid-satisfies-conditions:
class Solution:
    def satisfiesConditions(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        for i in range(m):
            for j in range(n):
                if i + 1 < m and grid[i][j] != grid[i + 1][j]:
                    return False
                if j + 1 < n and grid[i][j] == grid[i][j + 1]:
                    return False
        return True

check-if-it-is-a-straight-line:
class Solution:
    def checkStraightLine(self, coordinates: List[List[int]]) -> bool:
        (x1, y1), (x2, y2) = coordinates[0], coordinates[1]
        return all((x2 - x1) * (y - y1) == (y2 - y1) * (x - x1) for x, y in coordinates)

check-if-matrix-is-x-matrix:
class Solution:
    def checkXMatrix(self, grid: List[List[int]]) -> bool:
        n = len(grid)
        for i in range(n):
            for j in range(n):
                if i == j or i + j == n - 1:
                    if grid[i][j] == 0:
                        return False
                elif grid[i][j] != 0:
                    return False
        return True

check-if-n-and-its-double-exist:
class Solution:
    def checkIfExist(self, arr: List[int]) -> bool:
        seen = set()
        for x in arr:
            if x * 2 in seen or (x % 2 == 0 and x // 2 in seen):
                return True
            seen.add(x)
        return False

